SELECT c.company_id, c.name
FROM company c
WHERE EXISTS (
  SELECT 1 FROM game g WHERE g.publisher_company_id = c.company_id
)
AND NOT EXISTS (
  SELECT 1 FROM game g2 WHERE g2.developer_company_id = c.company_id
);

SELECT CASE WHEN COUNT(*) = 0 THEN 0.0 ELSE ROUND(100.0 * COUNT(*) FILTER (WHERE status = 'active') / COUNT(*)::numeric, 2) END AS percentage_active
FROM subscription
WHERE start_date >= DATE '2024-01-01' AND start_date < DATE '2025-01-01';

